<script lang="ts">
import SvgIcon from "$lib/components/ui/Icon.svelte";
import CardShell from "$lib/components/ats/CardShell.svelte";
import Input from "$lib/components/ui/Input.svelte";
import Button from "$lib/components/ui/Button.svelte";

import {untrack} from "svelte";
import {page as routePage,navigating} from "$app/state";
import {goto,invalidateAll} from "$app/navigation";
import {notify} from "$lib/client/toast";
type Application = { application: { id: string }; candidateName: string; jobTitle: string };
type Employee = { id: string; displayName: string };
type Interview = { interview: { id: string; status: string; scheduledAt: string; mode: string }; candidateName: string; jobTitle: string };
async function loadJson<T>(url: string): Promise<T> { const response = await fetch(url); const body = await response.json(); if (!response.ok || !body.success) throw new Error(body.error?.message ?? "Unable to load interview data."); return body; }
let applications=$state<Application[]>(untrack(()=>([])));
const setApplications=(next:typeof applications|((previous:typeof applications)=>typeof applications))=>{applications=typeof next==="function"?(next as (previous:typeof applications)=>typeof applications)(applications):next;};
let employees=$state<Employee[]>(untrack(()=>([])));
const setEmployees=(next:typeof employees|((previous:typeof employees)=>typeof employees))=>{employees=typeof next==="function"?(next as (previous:typeof employees)=>typeof employees)(employees):next;};
let interviews=$state<Interview[]>(untrack(()=>([])));
const setInterviews=(next:typeof interviews|((previous:typeof interviews)=>typeof interviews))=>{interviews=typeof next==="function"?(next as (previous:typeof interviews)=>typeof interviews)(interviews):next;};
let applicationId=$state(untrack(()=>("")));
const setApplicationId=(next:typeof applicationId|((previous:typeof applicationId)=>typeof applicationId))=>{applicationId=typeof next==="function"?(next as (previous:typeof applicationId)=>typeof applicationId)(applicationId):next;};
let interviewerEmployeeId=$state(untrack(()=>("")));
const setInterviewerEmployeeId=(next:typeof interviewerEmployeeId|((previous:typeof interviewerEmployeeId)=>typeof interviewerEmployeeId))=>{interviewerEmployeeId=typeof next==="function"?(next as (previous:typeof interviewerEmployeeId)=>typeof interviewerEmployeeId)(interviewerEmployeeId):next;};
let scheduledAt=$state(untrack(()=>("")));
const setScheduledAt=(next:typeof scheduledAt|((previous:typeof scheduledAt)=>typeof scheduledAt))=>{scheduledAt=typeof next==="function"?(next as (previous:typeof scheduledAt)=>typeof scheduledAt)(scheduledAt):next;};
let feedbackFor=$state(untrack(()=>("")));
const setFeedbackFor=(next:typeof feedbackFor|((previous:typeof feedbackFor)=>typeof feedbackFor))=>{feedbackFor=typeof next==="function"?(next as (previous:typeof feedbackFor)=>typeof feedbackFor)(feedbackFor):next;};
let recommendation=$state(untrack(()=>("recommended")));
const setRecommendation=(next:typeof recommendation|((previous:typeof recommendation)=>typeof recommendation))=>{recommendation=typeof next==="function"?(next as (previous:typeof recommendation)=>typeof recommendation)(recommendation):next;};
let comments=$state(untrack(()=>("")));
const setComments=(next:typeof comments|((previous:typeof comments)=>typeof comments))=>{comments=typeof next==="function"?(next as (previous:typeof comments)=>typeof comments)(comments):next;};
let busy=$state(untrack(()=>(false)));
const setBusy=(next:typeof busy|((previous:typeof busy)=>typeof busy))=>{busy=typeof next==="function"?(next as (previous:typeof busy)=>typeof busy)(busy):next;};
let loading=$state(untrack(()=>(true)));
const setLoading=(next:typeof loading|((previous:typeof loading)=>typeof loading))=>{loading=typeof next==="function"?(next as (previous:typeof loading)=>typeof loading)(loading):next;};
let message=$state(untrack(()=>("")));
const setMessage=(next:typeof message|((previous:typeof message)=>typeof message))=>{message=typeof next==="function"?(next as (previous:typeof message)=>typeof message)(message):next;};
let error=$state(untrack(()=>("")));
const setError=(next:typeof error|((previous:typeof error)=>typeof error))=>{error=typeof next==="function"?(next as (previous:typeof error)=>typeof error)(error):next;};
const load = async () => { setLoading(true); try { const [applicationBody, employeeBody, interviewBody] = await Promise.all([loadJson<{ applications: Application[] }>("/api/app/ats/applications"), loadJson<{ rows: Employee[] }>("/api/app/employees?pageSize=100"), loadJson<{ interviews: Interview[] }>("/api/app/ats/interviews/list")]); setApplications(applicationBody.applications); setEmployees(employeeBody.rows); setInterviews(interviewBody.interviews); } catch (cause) { setError(cause instanceof Error ? cause.message : "Unable to load interview data."); } finally { setLoading(false); } };
$effect(()=>{return untrack(() => { void load(); });});
const submit = async (event: SubmitEvent) => { event.preventDefault(); if(busy)return; setBusy(true); setError(""); setMessage(""); try { const response = await fetch("/api/app/ats/interviews", { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ applicationId, interviewerEmployeeIds: [interviewerEmployeeId], interviewType: "Interview", scheduledAt: new Date(scheduledAt).toISOString(), durationMinutes: 60, timezone: Intl.DateTimeFormat().resolvedOptions().timeZone, mode: "video" }) }); const body = await response.json(); if (!response.ok || !body.success) throw new Error(body.error?.message ?? "Unable to schedule interview."); setMessage("Interview scheduled."); await load(); } catch (cause) { setError(cause instanceof Error ? cause.message : "Unable to schedule interview."); } finally { setBusy(false); } };
const feedback = async (event: SubmitEvent) => { event.preventDefault(); if(busy)return; setBusy(true); setError(""); try { const response = await fetch(`/api/app/ats/interviews/${feedbackFor}/feedback`, { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ interviewerEmployeeId, recommendation, overallComments: comments.trim() }) }); const body = await response.json(); if (!response.ok || !body.success) throw new Error(body.error?.message ?? "Unable to submit feedback."); setMessage("Interview feedback submitted."); setFeedbackFor(""); setComments(""); await load(); } catch (cause) { setError(cause instanceof Error ? cause.message : "Unable to submit feedback."); } finally { setBusy(false); } };
</script>
<div class="space-y-4"><CardShell title="Schedule interview"><form onsubmit={submit} class="grid gap-3 md:grid-cols-4"><select required aria-label="Application to interview" class="h-10 rounded-lg border bg-surface px-3" value={applicationId} onchange={(event) => setApplicationId(event.currentTarget.value)}><option value="">Application</option>{#each applications as item}<option value={item.application.id}>{item.candidateName} · {item.jobTitle}</option>{/each}</select><select required aria-label="Interviewer" class="h-10 rounded-lg border bg-surface px-3" value={interviewerEmployeeId} onchange={(event) => setInterviewerEmployeeId(event.currentTarget.value)}><option value="">Interviewer</option>{#each employees as employee}<option value={employee.id}>{employee.displayName}</option>{/each}</select><Input required aria-label="Interview date and time" type="datetime-local" value={scheduledAt} onchange={(event) => setScheduledAt(event.currentTarget.value)} /><Button type="submit" disabled={busy}>Schedule interview</Button></form></CardShell>{#if error}<p role="alert" class="text-sm text-danger">{error}</p>{/if}{#if message}<p role="status" class="text-sm text-success">{message}</p>{/if}<CardShell title="Interview activity">{#if loading}<p class="text-sm text-muted">Loading interviews…</p>{:else}{#if interviews.length === 0}<p class="text-sm text-muted">No interviews scheduled yet.</p>{:else}<div class="space-y-2">{#each interviews as item}<div class="rounded-xl border p-3 text-sm"><div class="flex flex-wrap justify-between gap-2"><span class="font-medium">{item.candidateName} · {item.jobTitle}</span><span class="capitalize text-muted">{item.interview.status}</span></div><p class="text-muted">{new Date(item.interview.scheduledAt).toLocaleString()} · {item.interview.mode}</p><Button class="mt-2" size="sm" variant="secondary" onclick={() => setFeedbackFor(item.interview.id)}>Add feedback</Button></div>{/each}</div>{/if}{/if}</CardShell>{#if feedbackFor}<CardShell title="Interview feedback"><form onsubmit={feedback} class="grid gap-3"><select required aria-label="Feedback interviewer" class="h-10 rounded-lg border bg-surface px-3" value={interviewerEmployeeId} onchange={(event) => setInterviewerEmployeeId(event.currentTarget.value)}><option value="">Interviewer</option>{#each employees as employee}<option value={employee.id}>{employee.displayName}</option>{/each}</select><select aria-label="Recommendation" class="h-10 rounded-lg border bg-surface px-3" value={recommendation} onchange={(event) => setRecommendation(event.currentTarget.value)}><option value="recommended">Recommended</option><option value="hold">Hold</option><option value="not_recommended">Not recommended</option></select><textarea required class="min-h-24 rounded-lg border bg-surface p-3" placeholder="Overall comments" value={comments} oninput={(event) => setComments(event.currentTarget.value)}></textarea><Button type="submit" disabled={busy}>Submit feedback</Button></form></CardShell>{/if}</div>
